import { Accordion, Box, accordionItemBuilder } from '@wix/design-system';
import { Background, Category } from '@wix/wix-ui-icons-common';
import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { PanelHeader } from './../../../ui-components/panel-header/panel-header.js';
import { Panel } from './../../../ui-components/panel/panel.js';

import { DIVIDER_DESIGN_ACCORDION, DIVIDER_DESIGN_PANEL } from '../../data-hooks.js';
import { DividerAppearanceControls } from './divider-appearance-controls.js';
import { DividerColorControls } from './divider-color-controls.js';
import classes from './divider-design-panel-scss.js';
import { useDividerPanelClickOutside } from './use-divider-panel-click-outside.js';

export const DividerDesignPanel: React.FC<{
  closeModal: () => void;
  initiallyOpen?: 'appearance' | 'color';
  nodeId: string;
  referenceElement?: HTMLElement;
}> = ({ closeModal, initiallyOpen = 'color', nodeId, referenceElement }) => {
  const { t } = useContext(RicosContext);
  useDividerPanelClickOutside({ closeModal, referenceElement });

  return (
    <Panel
      closeButtonProps={{ onClick: closeModal }}
      dataHook={DIVIDER_DESIGN_PANEL}
      height="fit-content"
    >
      <PanelHeader title={t('DividerPlugin_Design_Title')} />
      <div className={classes.accordionContainer}>
        <Accordion
          dataHook={DIVIDER_DESIGN_ACCORDION}
          hideShadow
          horizontalPadding="small"
          skin="light"
          size="medium"
          items={[
            accordionItemBuilder({
              key: 'color',
              initiallyOpen: initiallyOpen === 'color',
              icon: <Background />,
              title: t('DividerPlugin_Color_Title'),
              children: (
                <Box direction="vertical" padding="SP1">
                  <DividerColorControls nodeId={nodeId} />
                </Box>
              ),
            }),
            accordionItemBuilder({
              key: 'appearance',
              initiallyOpen: initiallyOpen === 'appearance',
              icon: <Category />,
              title: t('DividerPlugin_Appearance_Title'),
              children: (
                <Box padding="SP1" direction="vertical">
                  <DividerAppearanceControls
                    nodeId={nodeId}
                    styleLabelKey="DividerPlugin_Appearance_Type"
                  />
                </Box>
              ),
            }),
          ]}
        />
      </div>
    </Panel>
  );
};
