import { Box, TextButton } from '@wix/design-system';
import { Adjust } from '@wix/wix-ui-icons-common';
import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { Panel } from './../../../ui-components/panel/panel.js';

import { DividerColorControls } from './divider-color-controls.js';
import { useDividerPanelClickOutside } from './use-divider-panel-click-outside.js';

export const DividerColorPanel: React.FC<{
  closeModal: () => void;
  nodeId: string;
  openDesignPanel: () => void;
  referenceElement?: HTMLElement;
}> = ({ closeModal, nodeId, openDesignPanel, referenceElement }) => {
  const { t } = useContext(RicosContext);
  useDividerPanelClickOutside({ closeModal, referenceElement });

  return (
    <Panel closeButtonProps={{ onClick: closeModal }} height="fit-content">
      <Box direction="vertical" gap="SP3" padding="SP3">
        <DividerColorControls nodeId={nodeId} />
        <TextButton
          style={{ justifyContent: 'center' }}
          size="small"
          prefixIcon={<Adjust />}
          onClick={openDesignPanel}
        >
          {t('DividerPlugin_AllDesignOptions')}
        </TextButton>
      </Box>
    </Panel>
  );
};
