import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { DropdownModal } from './../../../_shared/dropdown-modal/dropdown-modal.js';
import { ListItemSelect } from './../../../_shared/list-item-select/list-item-select.js';

type Props = {
  onSelect: (value: string) => void;
  selectedId?: string;
  closeModal: () => void;
  dropdownOptions: {
    dataHook: string;
    icon: React.ComponentType;
    iconMobile: React.ComponentType;
    label: string;
    id: string;
  }[];
};

export const LineStylePanel: React.FC<Props> = ({
  onSelect,
  selectedId,
  closeModal,
  dropdownOptions,
}) => {
  const { t, isMobile } = useContext(RicosContext);

  return (
    <DropdownModal
      onCloseButtonClick={closeModal}
      title={t('DividerPlugin_SelectType_Tooltip')}
      options={dropdownOptions.map(
        ({ dataHook, icon: Icon, iconMobile: IconMobile, label: text, id: commandKey }) => (
          <ListItemSelect
            key={commandKey}
            dataHook={dataHook}
            prefix={isMobile && IconMobile ? <IconMobile /> : Icon ? <Icon /> : null}
            title={t(text)}
            selected={commandKey === selectedId}
            onSelect={() => {
              onSelect(commandKey);
              closeModal();
            }}
          />
        )
      )}
    />
  );
};
