import { TIPTAP_DIVIDER_TYPE } from './../../ricos-content/index.js';
import { DividerData_LineStyle } from './../../ricos-schema/next-schema/index.js';
import type { ExtensionProps, NodeConfig, RicosExtension } from './../../ricos-types/index.js';
import { createRicosNodeExtension } from './../../plugin-commons/index.js';

import { Divider as Component } from './component.js';

export const tiptapExtensions = [
  createRicosNodeExtension({
    groups: ['overlay', 'draggable', 'not-overtypable'],
    type: 'react-node',
    reconfigure: (
      config: NodeConfig,
      _extensions: RicosExtension[],
      _props: ExtensionProps,
      settings: Record<string, unknown>
    ) => ({
      ...config,
      addOptions: () => settings,
    }),
    Component,
    name: TIPTAP_DIVIDER_TYPE,
    createExtensionConfig() {
      return {
        name: this.name,
        group:
          'block smartBlockCellContent layoutCellContent collapsibleListItemBodyContent tableCellContent',
        selectable: true,
        draggable: true,
        addAttributes: () => ({
          lineStyle: { default: DividerData_LineStyle.SINGLE },
          width: null,
          alignment: null,
          containerData: null,
          styles: null,
        }),
      };
    },
  }),
];
