import React, { useContext, useRef } from 'react';

import { ModalServiceContext, RicosContext, ZIndexContext } from './../../../ricos-context/index.js';
import { TEXT_COLOR_DEFAULT } from './../../../ricos-styles/theme-constants.js';
import { getResolvedColorPaletteColors } from './../../../ricos-styles/themeStrategy/generators/palette.js';
import { useNodeAttrs } from './../../../_shared/use-node-attrs.js';
import { ColorWithOpacityInput } from './../../../ui-components/color-with-opacity-input/color-with-opacity-input.js';

import { DIVIDER_MODALS } from '../../const.js';
import { DIVIDER_COLOR_INPUT, DIVIDER_COLOR_SWATCH } from '../../data-hooks.js';
import { normalizeDividerLine } from '../../normalize-divider-line.js';
import { DividerColorPicker } from './divider-color-picker.js';

export const DividerColorControls: React.FC<{ nodeId: string }> = ({ nodeId }) => {
  const { t, theme, isMobile } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext);
  const zIndexService = useContext(ZIndexContext);
  const colorPickerRef = useRef<HTMLDivElement>(null);
  const { patchPmNodeAttrs, pmNodeAttrs } = useNodeAttrs(nodeId, 'DIVIDER');

  if (!pmNodeAttrs || !patchPmNodeAttrs) {
    return null;
  }

  const normalizedStyles = normalizeDividerLine(pmNodeAttrs).styles;
  const themeColor = theme.colorPalette
    ? getResolvedColorPaletteColors(theme.colorPalette).textColor
    : undefined;
  const color = normalizedStyles.color ?? themeColor ?? TEXT_COLOR_DEFAULT;
  const onColorSelected = (nextColor: string | undefined) =>
    patchPmNodeAttrs({ styles: { ...normalizedStyles, color: nextColor } });

  const openColorPicker = () => {
    const referenceElement = colorPickerRef.current ?? undefined;
    modalService.togglePluginPanel?.({
      id: DIVIDER_MODALS.colorPicker,
      Component: DividerColorPicker,
      componentProps: {
        closeModal: () => modalService.closeModal(DIVIDER_MODALS.colorPicker),
        currentColor: color,
        onColorSelected,
        referenceElement,
      },
      isMobile,
      positioning: { referenceElement, placement: 'left' },
      onClickOutside: { on: 'pointerup', handler: () => undefined },
      focusReturnElement: referenceElement,
      // Keep the parent design/compact panel open while this nested picker is active.
      // An exclusive type would close the parent during togglePluginPanel's modal sweep.
      type: undefined,
    });
  };

  return (
    <div data-autofocus style={{ outline: 'none' }} tabIndex={-1}>
      <ColorWithOpacityInput
        fill={{
          type: 'color',
          color,
          onChange: onColorSelected,
          onChangeCommit: onColorSelected,
          allowTransparent: true,
        }}
        label={t('DividerPlugin_Color_Label')}
        inputDataHook={DIVIDER_COLOR_INPUT}
        fillPreviewDataHook={DIVIDER_COLOR_SWATCH}
        onColorPress={openColorPicker}
        colorPickerRef={colorPickerRef}
        zIndex={zIndexService.getZIndex('DIALOG')}
      />
    </div>
  );
};
