import type { DividerData, DividerData_LineStyle } from './../ricos-schema/next-schema/index.js';
import type { UnionToIntersection } from './../tiptap/core/index.js';
import { isDefined } from './../wix-rich-content-common/Utils/is-defined.js';

import { DIVIDER_STYLE_DEFAULTS } from './const.js';

// All style options across line styles, so shared helpers can read any option before
// normalization narrows a style object to the current line style.
export type DividerStyles = UnionToIntersection<NonNullable<DividerData['styles']>>;

// One line style's options that also forbid the other line styles' options, so a mismatched
// lineStyle/styles pairing cannot compile even when the styles object arrives via a variable.
type ExactStyles<S> = S & { [K in Exclude<keyof DividerStyles, keyof S>]?: never };

type StylesOf<L extends DividerData_LineStyle> = ExactStyles<
  NonNullable<Extract<DividerData, { lineStyle: L }>['styles']>
>;

// The schema-generated `DividerData` discriminated union is the source of truth for which style
// options each line style supports; narrowing the line style narrows the styles.
export type DividerLine = {
  [L in DividerData_LineStyle]: { lineStyle: L; styles?: StylesOf<L> };
}[DividerData_LineStyle];

// Accepts editor attrs too, where unset styles are `null` rather than absent. Every divider has a
// lineStyle; legacy dividers merely lack `styles`.
export type DividerLineInput = {
  [L in DividerData_LineStyle]: { lineStyle: L; styles?: StylesOf<L> | null };
}[DividerData_LineStyle];

const getNormalizedLineThickness = (lineThickness: number[] | undefined, lineCount: number) =>
  Array.from(
    { length: lineCount },
    (_, index) =>
      lineThickness?.[index] ??
      DIVIDER_STYLE_DEFAULTS.lineThickness[index] ??
      DIVIDER_STYLE_DEFAULTS.lineThickness[0]
  );

const getCommonStyles = (styles: DividerStyles | null | undefined, lineCount: number) => ({
  ...(isDefined(styles?.color) && { color: styles.color }),
  lineCap: styles?.lineCap ?? DIVIDER_STYLE_DEFAULTS.lineCap,
  lineThickness: getNormalizedLineThickness(styles?.lineThickness, lineCount),
});

/**
 * Fills the style options the divider's line style supports with defaults, dropping options that
 * belong to other line styles. A divider without data normalizes as a default SINGLE divider.
 */
export const normalizeDividerLine = (
  line: DividerLineInput | null | undefined
): Required<DividerLine> => {
  switch (line?.lineStyle) {
    case 'DOUBLE':
      return {
        lineStyle: 'DOUBLE',
        styles: {
          ...getCommonStyles(line.styles, 2),
          lineGap: line.styles?.lineGap ?? DIVIDER_STYLE_DEFAULTS.lineGap,
        },
      };
    case 'DASHED':
      return {
        lineStyle: 'DASHED',
        styles: {
          ...getCommonStyles(line.styles, 1),
          dashLength: line.styles?.dashLength ?? DIVIDER_STYLE_DEFAULTS.dashLength,
          dashGap: line.styles?.dashGap ?? DIVIDER_STYLE_DEFAULTS.dashGap,
        },
      };
    case 'DOTTED':
      return {
        lineStyle: 'DOTTED',
        styles: {
          ...getCommonStyles(line.styles, 1),
          dashGap: line.styles?.dashGap ?? DIVIDER_STYLE_DEFAULTS.dashGap,
        },
      };
    default:
      return { lineStyle: 'SINGLE', styles: getCommonStyles(line?.styles, 1) };
  }
};

// Switching the line style resets every style setting to its default; only the color carries over.
// The loose `lineStyle: string` absorbs untyped toolbar command keys - unknowns fall back to SINGLE.
export const getDividerLineAfterLineStyleChange = (
  lineStyle: string,
  styles: { color?: string | null } | null | undefined
): DividerLine => {
  const colorOnly = isDefined(styles?.color) ? { color: styles.color } : {};
  switch (lineStyle) {
    case 'DOUBLE':
      return { lineStyle: 'DOUBLE', styles: colorOnly };
    case 'DASHED':
      return { lineStyle: 'DASHED', styles: colorOnly };
    case 'DOTTED':
      return { lineStyle: 'DOTTED', styles: colorOnly };
    default:
      return { lineStyle: 'SINGLE', styles: colorOnly };
  }
};
