import { DividerSizeMedium, Minus } from '@wix/wix-ui-icons-common/lazy';
import React from 'react';

import { TIPTAP_DIVIDER_TYPE } from './../ricos-content/index.js';
import { DividerData_Alignment, DividerData_Width } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { Resolver, RicosServices, ToolbarButton } from './../ricos-types/index.js';
import { createPluginToolbarButton } from './../_shared/create-plugin-toolbar-button.js';
import { PLUGIN_TOOLBAR_ALIGNMENT_BUTTON } from './../_shared/data-hooks.js';
import { NODE_ALIGNMENT_BUTTONS } from './../_shared/node-alignment-dropdown/consts.js';
import { createAnimationButton } from './../_shared/plugin-toolbar/create-animation-button.js';
import { createDeleteButton } from './../_shared/plugin-toolbar/create-delete-button.js';
import { createSeparator } from './../_shared/plugin-toolbar/separator/create-separator.js';
import { getNodeAlignment } from './../_shared/resolvers/get-node-alignment.js';
import { getNodeInSelection } from './../_shared/resolvers/get-node-in-selection.js';
import { isVisibleOnlyOnDesktop } from './../_shared/resolvers/is-visible-only-on-desktop.js';

import { DIVIDER_BUTTONS } from './const.js';
import {
  PLUGIN_TOOLBAR_DIVIDER_SIZE_BUTTON,
  PLUGIN_TOOLBAR_DIVIDER_STYLE_BUTTON,
} from './data-hooks.js';
import { getDividerLineAfterLineStyleChange } from './normalize-divider-line.js';
import { createDividerDesignButtons } from './toolbar/buttons/create-divider-design-buttons.js';
import { DividerAlignmentButton } from './toolbar/buttons/divider-alignment-button.js';
import {
  alignmentMap,
  dividerSizeData,
  dividerStyleData,
} from './toolbar/buttons/divider-buttons-data.js';
import { DividerSizeButton } from './toolbar/buttons/divider-size-button.js';
import { DividerStyleButton } from './toolbar/buttons/divider-style-button.js';
import { DividerAlignmentPanel } from './toolbar/modals/divider-alignment-panel.js';
import { DividerSizePanel } from './toolbar/modals/divider-size-panel.js';
import { LineStylePanel } from './toolbar/modals/line-style-panel.js';

const resolveDividerAttribute =
  (attribute: string): Resolver =>
  content => {
    if (Array.isArray(content) && content.length > 0) {
      return content.find(node => node.type.name === TIPTAP_DIVIDER_TYPE)?.attrs?.[attribute];
    }
    return undefined;
  };

export const getToolbarButtons = (_config: $TSFixMe, services: RicosServices): ToolbarButton[] => {
  const {
    context: { isMobile },
  } = services;

  const styleButton: ToolbarButton = createPluginToolbarButton({
    id: DIVIDER_BUTTONS.style,
    type: 'dropdown',
    attributes: {
      nodeStyle: resolveDividerAttribute('lineStyle'),
      nodeStyles: resolveDividerAttribute('styles'),
      visible: () => isMobile,
      active: (_, { modals }) => Boolean(modals?.getModal(DIVIDER_BUTTONS.style)),
    },
    dataHook: PLUGIN_TOOLBAR_DIVIDER_STYLE_BUTTON,
    tooltip: 'DividerPlugin_SelectType_Tooltip',
    getIcon: ({ attributes }) => {
      return (
        dividerStyleData.find(({ commandKey }) => commandKey === attributes.nodeStyle)?.icon ||
        Minus
      );
    },
    command: ({
      modals,
      referenceElement,
      getComponentProps,
      tiptapEditor,
      attributes,
      publicCommands,
    }) => {
      const componentProps = getComponentProps?.({
        tiptapEditor,
        attributes,
        publicCommands,
        t: services.t,
        modals,
        languageDir: services.context.languageDir,
      });

      if (!componentProps) {
        return;
      }

      modals.isModalOpen(DIVIDER_BUTTONS.style)
        ? modals.closeModal(DIVIDER_BUTTONS.style)
        : modals.openModal({
            id: DIVIDER_BUTTONS.style,
            Component: LineStylePanel,
            componentProps,
            type: 'exclusive',
            layout: isMobile ? 'drawer' : 'floating',
            positioning: { referenceElement, placement: 'bottom' },
            onClickOutside: {
              on: 'pointerup',
              handler: e => {
                if (!referenceElement?.contains?.(e.target as Node)) {
                  modals.closeModal(DIVIDER_BUTTONS.style);
                  return;
                }
              },
            },
          });
    },
    Component: LineStylePanel,
    getComponentProps: ({ tiptapEditor, modals, attributes, t }) => ({
      dropdownOptions: dividerStyleData.map(option => ({
        id: option.commandKey,
        dataHook: option.dataHook,
        label: t(option.text),
        icon: option.iconSmall,
        iconMobile: option.icon,
      })),
      onSelect: (lineStyle: string) => {
        tiptapEditor
          .chain()
          .focus()
          .updateAttributes(
            TIPTAP_DIVIDER_TYPE,
            getDividerLineAfterLineStyleChange(lineStyle, attributes.nodeStyles ?? {})
          )
          .run();
      },
      selectedId: attributes.nodeStyle || 'SINGLE',
      closeModal: () => modals.closeModal(DIVIDER_BUTTONS.style),
    }),
    renderer: toolbarItem => (
      <DividerStyleButton toolbarItem={toolbarItem} id={DIVIDER_BUTTONS.style} />
    ),
  });

  const sizeButton: ToolbarButton = createPluginToolbarButton({
    id: DIVIDER_BUTTONS.size,
    type: 'dropdown',
    attributes: {
      nodeSize: resolveDividerAttribute('width'),
      selectedNode: getNodeInSelection,
      visible: isVisibleOnlyOnDesktop(isMobile),
      active: (_, { modals }) => Boolean(modals?.getModal(DIVIDER_BUTTONS.size)),
    },
    dataHook: PLUGIN_TOOLBAR_DIVIDER_SIZE_BUTTON,
    getIcon: ({ attributes }) => {
      const getSelectedSize: () => string = () => attributes.nodeSize || DividerData_Width.LARGE;
      const selectedSize = dividerSizeData.find(
        ({ commandKey }) => commandKey === getSelectedSize()
      );
      return selectedSize?.icon || DividerSizeMedium;
    },
    tooltip: 'ButtonModal_Size_Section',
    command: ({
      modals,
      referenceElement,
      getComponentProps,
      tiptapEditor,
      attributes,
      publicCommands,
    }) => {
      const componentProps = getComponentProps?.({
        tiptapEditor,
        attributes,
        publicCommands,
        t: services.t,
        modals,
        languageDir: services.context.languageDir,
      });

      if (!componentProps) {
        return;
      }

      modals.isModalOpen(DIVIDER_BUTTONS.size)
        ? modals.closeModal(DIVIDER_BUTTONS.size)
        : modals.openModal({
            id: DIVIDER_BUTTONS.size,
            Component: DividerSizePanel,
            componentProps,
            type: 'exclusive',
            layout: isMobile ? 'drawer' : 'floating',
            positioning: { referenceElement, placement: 'bottom' },
            onClickOutside: {
              on: 'pointerup',
              handler: e => {
                if (!referenceElement?.contains?.(e.target as Node)) {
                  modals.closeModal(DIVIDER_BUTTONS.size);
                  return;
                }
              },
            },
          });
    },
    Component: DividerSizePanel,
    getComponentProps: ({ tiptapEditor, modals, attributes, t }) => ({
      dropdownOptions: dividerSizeData.map(option => ({
        id: option.commandKey,
        dataHook: option.dataHook,
        label: t(option.text),
        icon: option.iconSmall,
        iconMobile: option.icon,
      })),
      onSelect: (value: string) => {
        const nodeContainerData = attributes.selectedNode.attrs?.containerData;
        const isFullWidth = value === DividerData_Width.LARGE;
        const newAttributes = isFullWidth
          ? {
              width: value,
              alignment: DividerData_Alignment.CENTER,
              containerData: {
                ...nodeContainerData,
                alignment: DividerData_Alignment.CENTER,
              },
            }
          : { width: value };
        tiptapEditor.chain().focus().updateAttributes(TIPTAP_DIVIDER_TYPE, newAttributes).run();
      },
      selectedId: attributes.nodeSize || DividerData_Width.LARGE,
      closeModal: () => modals.closeModal(DIVIDER_BUTTONS.size),
    }),
    renderer: toolbarItem => <DividerSizeButton toolbarItem={toolbarItem} />,
  });

  const alignmentButton: ToolbarButton = createPluginToolbarButton({
    id: DIVIDER_BUTTONS.alignment,
    type: 'dropdown',
    attributes: {
      nodeAlignment: getNodeAlignment,
      selectedNode: getNodeInSelection,
      visible: isVisibleOnlyOnDesktop(isMobile),
      active: (_, { modals }) => Boolean(modals?.getModal(DIVIDER_BUTTONS.alignment)),
    },
    dataHook: PLUGIN_TOOLBAR_ALIGNMENT_BUTTON,
    tooltip: 'TextAlignmentButton_Tooltip',
    getIcon: ({ services, attributes }) => {
      const selectedAlignment =
        attributes.nodeAlignment || getDefaultAlignment(services.context.languageDir);

      const SelectedAlignmentIcon = alignmentMap[selectedAlignment as keyof typeof alignmentMap];

      return SelectedAlignmentIcon;
    },
    Component: DividerAlignmentPanel,
    getComponentProps: ({ tiptapEditor, modals, attributes, t, languageDir }) => {
      return {
        closeModal: () => modals.closeModal(DIVIDER_BUTTONS.alignment),
        onSelect: (alignment: string) => {
          const nodeContainerData = attributes.selectedNode.attrs?.containerData;
          tiptapEditor
            .chain()
            .focus()
            .updateAttributes(TIPTAP_DIVIDER_TYPE, {
              alignment,
              containerData: { ...nodeContainerData, alignment },
            })
            .run();
        },
        selectedId: attributes.nodeAlignment || getDefaultAlignment(languageDir),
        options: Object.values(NODE_ALIGNMENT_BUTTONS).map(option => ({
          // Wixel renders this button as a segmented toggle and only picks up options with type 'button'.
          type: option.type,
          id: option.commandKey,
          dataHook: option.dataHook,
          label: t(option.text),
          icon: option.iconSmall,
        })),
      };
    },
    command: ({
      tiptapEditor,
      modals,
      referenceElement,
      attributes,
      getComponentProps,
      publicCommands,
    }) => {
      const componentProps = getComponentProps?.({
        tiptapEditor,
        attributes,
        publicCommands,
        t: services.t,
        modals,
        languageDir: services.context.languageDir,
      });

      if (!componentProps) {
        return;
      }

      modals.isModalOpen(DIVIDER_BUTTONS.alignment)
        ? modals.closeModal(DIVIDER_BUTTONS.alignment)
        : modals.openModal({
            id: DIVIDER_BUTTONS.alignment,
            Component: DividerAlignmentPanel,
            componentProps,
            type: 'exclusive',
            layout: isMobile ? 'drawer' : 'floating',
            positioning: { referenceElement, placement: 'bottom' },
            onClickOutside: {
              on: 'pointerup',
              handler: e => {
                if (!referenceElement?.contains?.(e.target as Node)) {
                  modals.closeModal(DIVIDER_BUTTONS.alignment);
                  return;
                }
              },
            },
          });
    },
    renderer: toolbarItem => (
      <DividerAlignmentButton id={DIVIDER_BUTTONS.alignment} toolbarItem={toolbarItem} />
    ),
  });
  const separator = createSeparator();
  const designSeparator = createSeparator();
  const animation = createAnimationButton(services);
  const deleteButton = createDeleteButton();
  const designButtons = createDividerDesignButtons(services);

  if (isMobile) {
    // no animation button — it's desktop only (see createAnimationButton)
    return [styleButton, separator, deleteButton];
  }

  if (services.context.environment === 'wixel') {
    return [sizeButton, alignmentButton, ...designButtons, animation, deleteButton];
  }

  return [
    sizeButton,
    alignmentButton,
    designSeparator,
    ...designButtons,
    animation,
    separator,
    deleteButton,
  ];
};

const getDefaultAlignment = (langDir: $TSFixMe) => {
  return langDir === 'rtl' ? 'RIGHT' : 'LEFT';
};
