import { FormField, SegmentedToggle } from '@wix/design-system';
import {
  BorderDashed,
  Equal,
  LineDotted,
  Minus,
  RoundedCorner,
  SquareCorner,
} from '@wix/wix-ui-icons-common';
import React from 'react';

import type {
  DividerData_LineStyle,
  DividerData_Styles_LineCap,
} from './../../../ricos-schema/next-schema/index.js';

import {
  DIVIDER_APPEARANCE_LINE_CAP,
  DIVIDER_APPEARANCE_STYLE,
  STYLE_DROPDOWN_OPTION_DASHED,
  STYLE_DROPDOWN_OPTION_DOTTED,
  STYLE_DROPDOWN_OPTION_DOUBLE,
  STYLE_DROPDOWN_OPTION_SINGLE,
} from '../../data-hooks.js';

export const DividerStyleToggle: React.FC<{
  ariaLabel: string;
  label: string;
  onChange: (value: DividerData_LineStyle) => void;
  tooltips: Record<DividerData_LineStyle, string>;
  value: DividerData_LineStyle;
}> = ({ ariaLabel, label, onChange, tooltips, value }) => (
  <FormField label={label}>
    <SegmentedToggle
      ariaLabel={ariaLabel}
      dataHook={DIVIDER_APPEARANCE_STYLE}
      fullWidth
      selected={value}
      size="small"
      onClick={(_, nextValue) => onChange(nextValue as DividerData_LineStyle)}
    >
      <SegmentedToggle.Icon
        dataHook={STYLE_DROPDOWN_OPTION_SINGLE}
        value="SINGLE"
        tooltipText={tooltips.SINGLE}
      >
        <Minus />
      </SegmentedToggle.Icon>
      <SegmentedToggle.Icon
        dataHook={STYLE_DROPDOWN_OPTION_DASHED}
        value="DASHED"
        tooltipText={tooltips.DASHED}
      >
        <BorderDashed />
      </SegmentedToggle.Icon>
      <SegmentedToggle.Icon
        dataHook={STYLE_DROPDOWN_OPTION_DOTTED}
        value="DOTTED"
        tooltipText={tooltips.DOTTED}
      >
        <LineDotted />
      </SegmentedToggle.Icon>
      <SegmentedToggle.Icon
        dataHook={STYLE_DROPDOWN_OPTION_DOUBLE}
        value="DOUBLE"
        tooltipText={tooltips.DOUBLE}
      >
        <Equal />
      </SegmentedToggle.Icon>
    </SegmentedToggle>
  </FormField>
);

export const DividerLineCapToggle: React.FC<{
  ariaLabel: string;
  label: string;
  onChange: (value: DividerData_Styles_LineCap) => void;
  roundTooltip: string;
  squareTooltip: string;
  value: DividerData_Styles_LineCap;
}> = ({ ariaLabel, label, onChange, roundTooltip, squareTooltip, value }) => (
  <FormField label={label}>
    <SegmentedToggle
      ariaLabel={ariaLabel}
      dataHook={DIVIDER_APPEARANCE_LINE_CAP}
      fullWidth
      selected={value}
      size="small"
      onClick={(_, nextValue) => onChange(nextValue as DividerData_Styles_LineCap)}
    >
      <SegmentedToggle.Icon value="SQUARE" tooltipText={squareTooltip}>
        <SquareCorner />
      </SegmentedToggle.Icon>
      <SegmentedToggle.Icon value="ROUND" tooltipText={roundTooltip}>
        <RoundedCorner />
      </SegmentedToggle.Icon>
    </SegmentedToggle>
  </FormField>
);
