import { definePmNodeConverter } from './../pm-converters/types.js';
import type { PmNodeJson } from './../pm-converters/types.js';
import type { DividerData, DividerNode } from './../ricos-schema/next-schema/index.js';
import { Node_Type } from './../ricos-schema/next-schema/index.js';
import { isDefined } from './../wix-rich-content-common/Utils/is-defined.js';

import { DIVIDER_STYLE_DEFAULTS } from './const.js';
import type { DividerLineInput, DividerStyles } from './normalize-divider-line.js';
import { normalizeDividerLine } from './normalize-divider-line.js';

const omitDefaultStyles = (line: DividerLineInput): DividerStyles | undefined => {
  if (!line.styles) {
    return undefined;
  }

  // Normalization drops the style fields that other line styles own, so the defaults diff below
  // only ever sees the fields the current line style supports.
  const relevantStyles: DividerStyles = normalizeDividerLine(line).styles;
  const { color, lineCap, lineThickness, dashLength, dashGap, lineGap } = relevantStyles;
  const defaultLineThickness = normalizeDividerLine({ lineStyle: line.lineStyle }).styles
    .lineThickness;
  const hasNonDefaultLineThickness =
    isDefined(lineThickness) &&
    lineThickness.length > 0 &&
    isDefined(defaultLineThickness) &&
    (lineThickness.length !== defaultLineThickness.length ||
      lineThickness.some((value, index) => value !== defaultLineThickness[index]));
  const nonDefaultStyles: DividerStyles = {
    ...(isDefined(color) && { color }),
    ...(isDefined(lineCap) && lineCap !== DIVIDER_STYLE_DEFAULTS.lineCap && { lineCap }),
    ...(hasNonDefaultLineThickness && { lineThickness }),
    ...(isDefined(dashLength) &&
      dashLength !== DIVIDER_STYLE_DEFAULTS.dashLength && { dashLength }),
    ...(isDefined(dashGap) && dashGap !== DIVIDER_STYLE_DEFAULTS.dashGap && { dashGap }),
    ...(isDefined(lineGap) && lineGap !== DIVIDER_STYLE_DEFAULTS.lineGap && { lineGap }),
  };

  // The empty object distinguishes configurable dividers from legacy dividers without styles.
  return nonDefaultStyles;
};

export const dividerConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.DIVIDER],
    convert: node => {
      // Only styled dividers get normalized styles; legacy dividers without styles must stay
      // style-less so they keep the legacy rendering.
      const pmStyles = node.dividerData?.styles && normalizeDividerLine(node.dividerData).styles;
      return {
        type: Node_Type.DIVIDER,
        attrs: {
          ...node.dividerData,
          ...(pmStyles && { styles: pmStyles }),
          id: node.id,
        },
      };
    },
  },
  fromPm: {
    types: [Node_Type.DIVIDER],
    convert: (node: PmNodeJson): DividerNode => {
      const { id, styles: pmStyles, animation, ...data } = node.attrs || {};
      const dividerData = data as DividerData;
      const styles = omitDefaultStyles({ lineStyle: dividerData.lineStyle, styles: pmStyles });
      return {
        type: Node_Type.DIVIDER,
        id,
        nodes: [],
        dividerData: {
          ...dividerData,
          ...(animation ? { animation } : {}),
          ...(styles !== undefined && { styles }),
        },
      };
    },
  },
});
