import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { DEFAULTS } from './defaults.js';
import type { DividerPluginViewerConfig } from './types.js';
import { DIVIDER_TYPE } from './types.js';
import { nodeViewRenderers } from './viewer/node-view-renderers.js';

export type { DividerPluginViewerConfig } from './types.js';

export const pluginDivider: ViewerPluginCreator<DividerPluginViewerConfig> = config => {
  return {
    config: { ...DEFAULTS.config, ...config },
    type: DIVIDER_TYPE,
    nodeViewRenderers,
  };
};
