import { Divider, DividerSmall } from '@wix/wix-ui-icons-common/lazy';

import defaultComponentData from './../ricos-schema/legacy/statics/divider.defaults.json.js';
import {
  type EditorPluginCreator,
  Node_Type,
  RicosPluginToolbarNames,
  quickActionsModalSections,
} from './../ricos-types/index.js';

import { DEFAULTS } from './defaults.js';
import { dividerConverter } from './divider-converter.js';
import { getAddButtons } from './get-add-buttons.js';
import { getToolbarButtons } from './get-toolbar-buttons.js';
import { tiptapExtensions } from './tiptap/tiptap.js';
import type { DividerPluginEditorConfig } from './types.js';
import { DIVIDER_TYPE } from './types.js';

export const pluginDivider: EditorPluginCreator<DividerPluginEditorConfig> = config => {
  const pluginConfig = { type: 'divider' as const, ...DEFAULTS.config, ...config };
  return {
    config: pluginConfig,
    pmMarkConverters: [],
    pmNodeConverters: [dividerConverter],
    type: DIVIDER_TYPE,
    tiptapExtensions,
    getAddButtons: (config, services) => getAddButtons(config, services),
    toolbar: {
      names: [RicosPluginToolbarNames.DIVIDER],
      getButtons: (config, services) => getToolbarButtons(config, services),
    },
    getQuickActions: ({ pluginServices }) => [
      {
        id: Node_Type.DIVIDER,
        title: 'QuickActionsPlugin_ActionTitle_Divider',
        icon: pluginServices?.context.isMobile ? Divider : DividerSmall,
        section: quickActionsModalSections.FormatLayout,
        tags: ['separator', 'line', 'break', 'horizontal rule', 'section divider'],
        command: ({ publicCommands }) => {
          publicCommands.insertBlockWithBlankLines(DIVIDER_TYPE, defaultComponentData);
        },
      },
    ],
  };
};
