import { DividerSizeMedium } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../../ricos-modals/modal-service-provider.js';
import { DividerData_Width } from './../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { IToolbarItem } from './../../../ricos-types/index.js';
import { DropdownButton } from './../../../_shared/dropdown-button.js';

import { DIVIDER_BUTTONS } from '../../const.js';
import { dividerSizeData } from './divider-buttons-data.js';

type Props = {
  toolbarItem: IToolbarItem;
  dataHook?: string;
};

export const DividerSizeButton: FC<Props> = ({ toolbarItem, dataHook }) => {
  const { t } = useContext(RicosContext);
  const isModalOpen = useModalState(getIsModalOpen(DIVIDER_BUTTONS.size));
  const [referenceElement, setReferenceElement] = useState<HTMLElement | null>(null);
  const getSelectedSize: () => string = () =>
    toolbarItem?.attributes.nodeSize || DividerData_Width.LARGE;
  const selectedSize = dividerSizeData.find(({ commandKey }) => commandKey === getSelectedSize());
  const icon = selectedSize?.icon || DividerSizeMedium;

  return (
    <DropdownButton
      dataHook={dataHook}
      active={isModalOpen}
      onClick={() => {
        toolbarItem.commands.click({ referenceElement });
      }}
      ref={setReferenceElement}
      icon={icon}
      tooltip={t('ButtonModal_Size_Section')}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
