import { Box, Input } from '@wix/design-system';
import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import type {
  DividerData_LineStyle,
  DividerData_Styles_LineCap,
} from './../../../ricos-schema/next-schema/index.js';
import { useNodeAttrs } from './../../../_shared/use-node-attrs.js';
import { SliderWithInput } from './../../../ui-components/slider-with-input/slider-with-input.js';

import { DIVIDER_STYLE_DEFAULTS, DIVIDER_STYLE_LIMITS } from '../../const.js';
import {
  getDividerLineAfterLineStyleChange,
  normalizeDividerLine,
} from '../../normalize-divider-line.js';
import { DividerLineCapToggle, DividerStyleToggle } from './divider-segmented-controls.js';

const sliderDataHook = (field: string) => `divider-${field}-slider`;
const inputDataHook = (field: string) => `divider-${field}-input`;

const DividerStyleSlider: React.FC<{
  field: string;
  label: string;
  min: number;
  max: number;
  value: number;
  onChange: (value: number) => void;
}> = ({ field, label, min, max, value, onChange }) => (
  <SliderWithInput
    min={min}
    max={max}
    label={label}
    sliderDataHook={sliderDataHook(field)}
    inputDataHook={inputDataHook(field)}
    value={value}
    onChange={onChange}
    suffix={<Input.Affix>px</Input.Affix>}
  />
);

export const DividerAppearanceControls: React.FC<{
  nodeId: string;
  styleLabelKey?: string;
}> = ({ nodeId, styleLabelKey = 'DividerPlugin_Appearance_Style' }) => {
  const { t } = useContext(RicosContext);
  const { patchPmNodeAttrs, pmNodeAttrs } = useNodeAttrs(nodeId, 'DIVIDER');

  if (!pmNodeAttrs || !patchPmNodeAttrs) {
    return null;
  }

  const line = normalizeDividerLine(pmNodeAttrs);
  const lineThicknessValue = (index: number) =>
    line.styles.lineThickness?.[index] ??
    DIVIDER_STYLE_DEFAULTS.lineThickness[index] ??
    DIVIDER_STYLE_LIMITS.lineThickness.min;
  const patchLineThickness = (index: number) => (value: number) => {
    const lineThickness = [...(line.styles.lineThickness ?? [])];
    lineThickness[index] = value;
    patchPmNodeAttrs({ styles: { ...line.styles, lineThickness } });
  };

  return (
    <Box direction="vertical" gap="SP2">
      <DividerStyleToggle
        ariaLabel={t(styleLabelKey)}
        label={t(styleLabelKey)}
        value={line.lineStyle}
        onChange={(value: DividerData_LineStyle) =>
          patchPmNodeAttrs(getDividerLineAfterLineStyleChange(value, line.styles))
        }
        tooltips={{
          SINGLE: t('DividerPlugin_SingleLineStyleOption'),
          DASHED: t('DividerPlugin_DashedLineStyleOption'),
          DOTTED: t('DividerPlugin_DottedLineStyleOption'),
          DOUBLE: t('DividerPlugin_DoubleLineStyleOption'),
        }}
      />
      <DividerLineCapToggle
        ariaLabel={t('DividerPlugin_Appearance_EndPoints')}
        label={t('DividerPlugin_Appearance_EndPoints')}
        value={line.styles.lineCap ?? 'SQUARE'}
        onChange={(value: DividerData_Styles_LineCap) =>
          patchPmNodeAttrs({ styles: { ...line.styles, lineCap: value } })
        }
        squareTooltip={t('DividerPlugin_Appearance_EndPointSquare')}
        roundTooltip={t('DividerPlugin_Appearance_EndPointRound')}
      />
      {line.lineStyle === 'DOUBLE' ? (
        <>
          <DividerStyleSlider
            field="lineThickness-0"
            label={t('DividerPlugin_Appearance_FirstLineWidth')}
            {...DIVIDER_STYLE_LIMITS.lineThickness}
            value={lineThicknessValue(0)}
            onChange={patchLineThickness(0)}
          />
          <DividerStyleSlider
            field="lineThickness-1"
            label={t('DividerPlugin_Appearance_SecondLineWidth')}
            {...DIVIDER_STYLE_LIMITS.lineThickness}
            value={lineThicknessValue(1)}
            onChange={patchLineThickness(1)}
          />
          <DividerStyleSlider
            field="lineGap"
            label={t('DividerPlugin_Appearance_SpaceBetweenLines')}
            {...DIVIDER_STYLE_LIMITS.lineGap}
            value={line.styles.lineGap ?? DIVIDER_STYLE_DEFAULTS.lineGap}
            onChange={value => patchPmNodeAttrs({ styles: { ...line.styles, lineGap: value } })}
          />
        </>
      ) : (
        <>
          <DividerStyleSlider
            field="lineThickness-0"
            label={t('DividerPlugin_Appearance_Width')}
            {...DIVIDER_STYLE_LIMITS.lineThickness}
            value={lineThicknessValue(0)}
            onChange={patchLineThickness(0)}
          />
          {line.lineStyle === 'DASHED' && (
            <>
              <DividerStyleSlider
                field="dashLength"
                label={t('DividerPlugin_Appearance_DashLength')}
                {...DIVIDER_STYLE_LIMITS.dashLength}
                value={line.styles.dashLength ?? DIVIDER_STYLE_DEFAULTS.dashLength}
                onChange={value =>
                  patchPmNodeAttrs({ styles: { ...line.styles, dashLength: value } })
                }
              />
              <DividerStyleSlider
                field="dashGap"
                label={t('DividerPlugin_Appearance_SpaceBetweenDashes')}
                {...DIVIDER_STYLE_LIMITS.dashGap}
                value={line.styles.dashGap ?? DIVIDER_STYLE_DEFAULTS.dashGap}
                onChange={value => patchPmNodeAttrs({ styles: { ...line.styles, dashGap: value } })}
              />
            </>
          )}
          {line.lineStyle === 'DOTTED' && (
            <DividerStyleSlider
              field="dashGap"
              label={t('DividerPlugin_Appearance_SpaceBetweenDots')}
              {...DIVIDER_STYLE_LIMITS.dashGap}
              value={line.styles.dashGap ?? DIVIDER_STYLE_DEFAULTS.dashGap}
              onChange={value => patchPmNodeAttrs({ styles: { ...line.styles, dashGap: value } })}
            />
          )}
        </>
      )}
    </Box>
  );
};
