import { useContext } from 'react';

import { ModalServiceContext } from './../../../ricos-context/modal-context.js';
import {
  useClickOutside,
  usePanelContainerElement,
} from './../../../ui-components/index.js';

import { DIVIDER_MODALS } from '../../const.js';

export const useDividerPanelClickOutside = ({
  closeModal,
  referenceElement,
}: {
  closeModal: () => void;
  referenceElement?: HTMLElement;
}) => {
  const modalService = useContext(ModalServiceContext);
  const containerEl = usePanelContainerElement();

  useClickOutside({
    containerRef: { current: containerEl },
    onClickOutside: event => {
      const target = event.target as HTMLElement | null;
      if (referenceElement?.contains(target as Node) || target?.closest('[role="tooltip"]')) {
        return;
      }
      closeModal();
    },
    disable: modalService.isModalOpen(DIVIDER_MODALS.colorPicker),
  });
};
