import { Background, Category, DesignSettings } from '@wix/wix-ui-icons-common';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../../ricos-modals/modal-service-provider.js';
import type { IToolbarItem, RicosServices, ToolbarButton } from './../../../ricos-types/index.js';
import { createPluginToolbarButton } from './../../../_shared/create-plugin-toolbar-button.js';
import { getNodeInSelection } from './../../../_shared/resolvers/get-node-in-selection.js';
import { isVisibleOnlyOnDesktop } from './../../../_shared/resolvers/is-visible-only-on-desktop.js';
import { ToolbarButton as ToolbarButtonComponent } from './../../../_shared/toolbar-button/toolbar-button.js';
import { FLOATING_PLUGIN_TOOLBAR } from './../../../toolbars-v3/index.js';

import { DIVIDER_BUTTONS, DIVIDER_MODALS } from '../../const.js';
import {
  PLUGIN_TOOLBAR_DIVIDER_APPEARANCE_BUTTON,
  PLUGIN_TOOLBAR_DIVIDER_COLOR_BUTTON,
  PLUGIN_TOOLBAR_DIVIDER_DESIGN_BUTTON,
} from '../../data-hooks.js';
import { DividerAppearancePanel } from '../modals/divider-appearance-panel.js';
import { DividerColorPanel } from '../modals/divider-color-panel.js';
import { DividerDesignPanel } from '../modals/divider-design-panel.js';

type DesignButtonConfig = {
  Component: FC<any>;
  dataHook: string;
  icon: FC;
  id: string;
  modalId: string;
  section: 'appearance' | 'color';
  tooltip: string;
};

const BUTTONS: DesignButtonConfig[] = [
  {
    Component: DividerColorPanel,
    dataHook: PLUGIN_TOOLBAR_DIVIDER_COLOR_BUTTON,
    icon: Background,
    id: DIVIDER_BUTTONS.color,
    modalId: DIVIDER_MODALS.color,
    section: 'color',
    tooltip: 'DividerPlugin_Color_Title',
  },
  {
    Component: DividerAppearancePanel,
    dataHook: PLUGIN_TOOLBAR_DIVIDER_APPEARANCE_BUTTON,
    icon: Category,
    id: DIVIDER_BUTTONS.appearance,
    modalId: DIVIDER_MODALS.appearance,
    section: 'appearance',
    tooltip: 'DividerPlugin_Appearance_Title',
  },
];

export const createDividerDesignButtons = (services: RicosServices): ToolbarButton[] => {
  const openDesignPanel = ({
    initiallyOpen,
    nodeId,
    referenceElement,
  }: {
    initiallyOpen: 'appearance' | 'color';
    nodeId: string;
    referenceElement?: HTMLElement;
  }) => {
    services.modals.togglePluginPanel({
      id: DIVIDER_MODALS.design,
      Component: DividerDesignPanel,
      componentProps: {
        closeModal: () => services.modals.closeModal(DIVIDER_MODALS.design),
        initiallyOpen,
        nodeId,
        referenceElement,
      },
      positioning: {
        referenceElement:
          referenceElement?.closest(`[data-hook~=${FLOATING_PLUGIN_TOOLBAR}]`) ?? referenceElement,
        placement: 'right-start',
      },
      // DividerDesignPanel handles outside clicks so it can ignore portaled tooltips and pickers.
      onClickOutside: { on: 'pointerup', handler: () => undefined },
      focusReturnElement: referenceElement,
      isMobile: false,
    });
  };

  const compactButtons = BUTTONS.map(config =>
    createPluginToolbarButton({
      id: config.id,
      type: 'modal',
      attributes: {
        active: (_, { modals }) => Boolean(modals?.getModal(config.modalId)),
        selectedNode: getNodeInSelection,
        visible: isVisibleOnlyOnDesktop(services.context.isMobile),
      },
      dataHook: config.dataHook,
      icon: config.icon,
      tooltip: config.tooltip,
      command: ({ attributes, modals, referenceElement }) => {
        const nodeId = attributes.selectedNode?.attrs.id;
        if (!nodeId) {
          return;
        }
        const closeModal = () => modals.closeModal(config.modalId);
        const openFullDesignPanel = () => {
          closeModal();
          openDesignPanel({ initiallyOpen: config.section, nodeId, referenceElement });
        };

        modals.isModalOpen(config.modalId)
          ? closeModal()
          : modals.openModal({
              id: config.modalId,
              Component: config.Component,
              componentProps: {
                closeModal,
                nodeId,
                openDesignPanel: openFullDesignPanel,
                referenceElement,
              },
              type: 'exclusive',
              layout: 'floating',
              positioning: { referenceElement, placement: 'bottom' },
              // The panel handles outside clicks so it can ignore portaled tooltips and pickers.
              onClickOutside: { on: 'pointerup', handler: () => undefined },
            });
      },
      renderer: toolbarItem => (
        <DividerPanelButton
          toolbarItem={toolbarItem}
          dataHook={config.dataHook}
          icon={config.icon}
          modalId={config.modalId}
          tooltip={config.tooltip}
        />
      ),
    })
  );

  const designButton = createPluginToolbarButton({
    id: DIVIDER_BUTTONS.design,
    type: 'modal',
    attributes: {
      active: (_, { modals }) => Boolean(modals?.getModal(DIVIDER_MODALS.design)),
      selectedNode: getNodeInSelection,
      visible: isVisibleOnlyOnDesktop(services.context.isMobile),
    },
    dataHook: PLUGIN_TOOLBAR_DIVIDER_DESIGN_BUTTON,
    icon: DesignSettings,
    tooltip: 'DividerPlugin_AllDesignOptions',
    command: ({ attributes, referenceElement }) => {
      const nodeId = attributes.selectedNode?.attrs.id;
      if (!nodeId) {
        return;
      }
      services.modals.isModalOpen(DIVIDER_MODALS.design)
        ? services.modals.closeModal(DIVIDER_MODALS.design)
        : openDesignPanel({ initiallyOpen: 'color', nodeId, referenceElement });
    },
    renderer: toolbarItem => (
      <DividerPanelButton
        toolbarItem={toolbarItem}
        dataHook={PLUGIN_TOOLBAR_DIVIDER_DESIGN_BUTTON}
        icon={DesignSettings}
        modalId={DIVIDER_MODALS.design}
        tooltip="DividerPlugin_AllDesignOptions"
      />
    ),
  });

  return [...compactButtons, designButton];
};

const DividerPanelButton: FC<{
  dataHook: string;
  icon: FC;
  modalId: string;
  toolbarItem: IToolbarItem;
  tooltip: string;
}> = ({ dataHook, icon, modalId, toolbarItem, tooltip }) => {
  const { t } = useContext(RicosContext);
  const isModalOpen = useModalState(getIsModalOpen(modalId));
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);

  return (
    <ToolbarButtonComponent
      active={isModalOpen}
      dataHook={dataHook}
      prefix={icon}
      ref={setReferenceElement}
      tabIndex={toolbarItem.presentation.tabIndex}
      tooltip={t(tooltip)}
      onClick={() => toolbarItem.commands.click({ referenceElement })}
    />
  );
};
