import { Minus } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../../ricos-modals/modal-service-provider.js';
import type { IToolbarItem } from './../../../ricos-types/index.js';
import { DropdownButton } from './../../../_shared/dropdown-button.js';

import { dividerStyleData } from './divider-buttons-data.js';

type Props = {
  toolbarItem: IToolbarItem;
  id: string;
  dataHook?: string;
};

export const DividerStyleButton: FC<Props> = ({ toolbarItem, dataHook, id }) => {
  const { t } = useContext(RicosContext) || {};
  const isModalOpen = useModalState(getIsModalOpen(id));
  const [referenceElement, setReferenceElement] = useState<HTMLElement | null>(null);

  const SelectedStyleIcon =
    dividerStyleData.find(({ commandKey }) => commandKey === toolbarItem?.attributes.nodeStyle)
      ?.icon || Minus;

  return (
    <DropdownButton
      dataHook={dataHook}
      active={isModalOpen}
      onClick={() => toolbarItem.commands.click({ referenceElement })}
      ref={setReferenceElement}
      icon={SelectedStyleIcon}
      tooltip={t('DividerPlugin_SelectType_Tooltip')}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
