import { Divider } from '@wix/wix-ui-icons-common/lazy';

import { Node_Type } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import defaultComponentData from './../ricos-schema/legacy/statics/divider.defaults.json.js';
import type { AddButton } from './../ricos-types/index.js';
import { INSERT_PLUGIN_BUTTONS, TOOLBARS } from './../editor-common/index.js';

import { INSERT_DIVIDER_BUTTON } from './data-hooks.js';
import { DIVIDER_TYPE } from './types.js';

export const toolbarsToAddIn: (TOOLBARS.MOBILE | TOOLBARS.FOOTER | TOOLBARS.SIDE)[] = [
  TOOLBARS.MOBILE,
  TOOLBARS.FOOTER,
  TOOLBARS.SIDE,
];

export const getAddButtons = (_config: $TSFixMe, _services: $TSFixMe): AddButton[] => {
  return [
    {
      id: Node_Type.DIVIDER,
      icon: Divider,
      label: INSERT_PLUGIN_BUTTONS.DIVIDER,
      dataHook: INSERT_DIVIDER_BUTTON,
      tooltip: 'DividerPlugin_InsertButton_Tooltip',
      toolbars: toolbarsToAddIn,
      command: ({ publicCommands }) => {
        publicCommands.insertBlockWithBlankLines(DIVIDER_TYPE, defaultComponentData);
        return true;
      },
      menuConfig: {
        tags: 'Divider_plugin_search_tags',
      },
    },
  ];
};
