import { Box, FormField, SegmentedToggle } from '@wix/design-system';
import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { Panel } from './../../../ui-components/panel/panel.js';

type Props = {
  onSelect: (value: string) => void;
  selectedId?: string;
  closeModal: () => void;
  dropdownOptions: {
    dataHook: string;
    icon: React.ComponentType;
    iconMobile: React.ComponentType;
    label: string;
    id: string;
  }[];
};

export const DividerSizePanel: React.FC<Props> = ({
  onSelect,
  selectedId,
  closeModal,
  dropdownOptions,
}) => {
  const { t } = useContext(RicosContext);

  return (
    <Panel closeButtonProps={{ onClick: closeModal }} height="fit-content">
      <Box padding="SP3">
        <FormField label={t('ButtonModal_Size_Section')}>
          <SegmentedToggle
            ariaLabel={t('ButtonModal_Size_Section')}
            fullWidth
            selected={selectedId}
            size="small"
            onClick={(_, commandKey) => {
              onSelect(commandKey);
              closeModal();
            }}
          >
            {dropdownOptions.map(({ dataHook, icon: Icon, label: text, id: commandKey }) => (
              <SegmentedToggle.Icon
                key={commandKey}
                dataHook={dataHook}
                value={commandKey}
                tooltipText={t(text)}
              >
                <Icon />
              </SegmentedToggle.Icon>
            ))}
          </SegmentedToggle>
        </FormField>
      </Box>
    </Panel>
  );
};
