import React, { useContext, useEffect, useMemo, useState } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import {
  handleColorAdded,
  handleColorDeleted,
  resolveThemeColorsPalette,
  useResolvedCustomColors,
} from './../../../_shared/color-manager-utils.js';
import { NewColorPicker } from './../../../ui-components/color-picker/new-color-picker/index.js';

type Props = {
  closeModal: () => void;
  currentColor?: string;
  onColorSelected: (color: string | undefined) => void;
  referenceElement?: HTMLElement;
};

export const DividerColorPicker: React.FC<Props> = ({
  closeModal,
  currentColor,
  onColorSelected,
  referenceElement,
}) => {
  const { t, theme, colorManager } = useContext(RicosContext);
  const themeColors = useMemo(() => resolveThemeColorsPalette(theme), [theme]);
  const customColors = useResolvedCustomColors(colorManager);
  const [selectedColor, setSelectedColor] = useState(currentColor);

  useEffect(() => setSelectedColor(currentColor), [currentColor]);

  const handleColorSelected = (color: string | undefined) => {
    setSelectedColor(color);
    onColorSelected(color);
  };

  return (
    <NewColorPicker
      themeColors={themeColors}
      customColors={customColors}
      currentColor={selectedColor}
      title={t('DividerPlugin_Color_Title')}
      closeModal={closeModal}
      onColorSelected={handleColorSelected}
      onColorAdded={color => {
        handleColorAdded(color, colorManager);
        handleColorSelected(color);
      }}
      onColorDeleted={color => handleColorDeleted(color, colorManager)}
      onResetColor={() => handleColorSelected(undefined)}
      referenceElement={referenceElement}
      allowTransparent
      logBi={() => {}}
    />
  );
};
