import { resolveDocumentColorToCss } from './../_shared/theme-color-token.js';

import { DIVIDER_STYLE_DEFAULTS, DIVIDER_STYLE_LIMITS } from './const.js';
import type { DividerLineInput } from './normalize-divider-line.js';
import { normalizeDividerLine } from './normalize-divider-line.js';

type LegacyDividerLine = {
  x1: number;
  x2: string;
  y1: number;
  y2: number;
  strokeWidth: number;
  strokeDasharray?: string;
};

type StyledDividerLine = {
  thickness: number;
  borderRadius?: number;
  mask?: { image: string; overhang: number };
};

export type DividerRenderData =
  | {
      kind: 'legacy';
      height: number;
      lines: LegacyDividerLine[];
      strokeLinecap: 'butt';
    }
  | {
      kind: 'lines';
      height: number;
      color?: string;
      lineGap?: number;
      lines: StyledDividerLine[];
    };

const clamp = (value: number | undefined, fallback: number, min: number, max: number) => {
  const safeValue = typeof value === 'number' && Number.isFinite(value) ? value : fallback;
  return Math.min(max, Math.max(min, safeValue));
};

const getLegacyLineGeometry = (y: number) => ({
  x1: 0,
  x2: '100%',
  y1: y,
  y2: y,
  strokeWidth: 1,
});

/**
 * The dash pattern is a one-dash SVG tile applied as a CSS mask with `mask-repeat: space`: the
 * browser draws as many whole tiles as fit at their exact authored pixel sizes and widens the gaps
 * evenly with the leftover, so the dash count adapts to whatever width the divider renders at
 * without a dash ever being scaled or cut - and with no measurement, server and client markup are
 * identical. The rect is the visible dash (unlike an SVG stroke there is no cap overhang to
 * compensate), and the tile's trailing gap is cancelled by the line overhanging its clipping
 * wrapper by one gap, which puts the first and last dash flush with the divider's edges.
 */
const getDashMask = (visibleDash: number, dashGap: number, thickness: number, rounded: boolean) => {
  const tileWidth = visibleDash + dashGap;
  const cornerRadius = rounded ? thickness / 2 : 0;
  const dash = `<rect width="${visibleDash}" height="${thickness}" rx="${cornerRadius}"/>`;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${tileWidth}" height="${thickness}">${dash}</svg>`;
  const image = `url("data:image/svg+xml,${encodeURIComponent(svg)}")`;

  return { image, overhang: dashGap };
};

export const getDividerRenderData = (line: DividerLineInput | undefined): DividerRenderData => {
  const lineStyle = line?.lineStyle;
  if (!line?.styles) {
    // Legacy documents keep the original rendering: full width lines with a pixel dash pattern.
    return {
      kind: 'legacy',
      height: lineStyle === 'DOUBLE' ? 8 : 2,
      lines: (lineStyle === 'DOUBLE' ? [1, 7] : [1]).map(y => ({
        ...getLegacyLineGeometry(y),
        strokeDasharray:
          lineStyle === 'DASHED' ? '4 4' : lineStyle === 'DOTTED' ? '1 5' : undefined,
      })),
      strokeLinecap: 'butt',
    };
  }

  const normalized = normalizeDividerLine(line);
  const firstLineThickness = clamp(
    normalized.styles.lineThickness?.[0],
    DIVIDER_STYLE_DEFAULTS.lineThickness[0],
    DIVIDER_STYLE_LIMITS.lineThickness.min,
    DIVIDER_STYLE_LIMITS.lineThickness.max
  );
  const rounded = normalized.styles.lineCap === 'ROUND';
  const color = resolveDocumentColorToCss(normalized.styles.color);
  // A round end point rounds a solid line's ends the way it rounds each dash's ends.
  const getSolidLine = (thickness: number): StyledDividerLine => ({
    thickness,
    ...(rounded && { borderRadius: thickness / 2 }),
  });

  if (normalized.lineStyle === 'DOUBLE') {
    const secondLineThickness = clamp(
      normalized.styles.lineThickness?.[1],
      DIVIDER_STYLE_DEFAULTS.lineThickness[1],
      DIVIDER_STYLE_LIMITS.lineThickness.min,
      DIVIDER_STYLE_LIMITS.lineThickness.max
    );
    const lineGap = clamp(
      normalized.styles.lineGap,
      DIVIDER_STYLE_DEFAULTS.lineGap,
      DIVIDER_STYLE_LIMITS.lineGap.min,
      DIVIDER_STYLE_LIMITS.lineGap.max
    );

    return {
      kind: 'lines',
      color,
      height: firstLineThickness + lineGap + secondLineThickness,
      lineGap,
      lines: [getSolidLine(firstLineThickness), getSolidLine(secondLineThickness)],
    };
  }

  const isPatterned = normalized.lineStyle === 'DASHED' || normalized.lineStyle === 'DOTTED';
  const dashLength =
    normalized.lineStyle === 'DASHED'
      ? clamp(
          normalized.styles.dashLength,
          DIVIDER_STYLE_DEFAULTS.dashLength,
          DIVIDER_STYLE_LIMITS.dashLength.min,
          DIVIDER_STYLE_LIMITS.dashLength.max
        )
      : 0;
  const dashGap = clamp(
    isPatterned ? normalized.styles.dashGap : undefined,
    DIVIDER_STYLE_DEFAULTS.dashGap,
    DIVIDER_STYLE_LIMITS.dashGap.min,
    DIVIDER_STYLE_LIMITS.dashGap.max
  );
  // A dash can never render shorter than the line is thick - it becomes a dot, which with a round
  // end point is a circle. A dot has no length of its own - its size is the line thickness.
  const visibleDash = Math.max(dashLength, firstLineThickness);

  return {
    kind: 'lines',
    color,
    height: firstLineThickness,
    lines: [
      {
        ...getSolidLine(firstLineThickness),
        ...(isPatterned && {
          mask: getDashMask(visibleDash, dashGap, firstLineThickness, rounded),
        }),
      },
    ],
  };
};
