import React from 'react';

import type { DividerNode } from './../../ricos-schema/next-schema/index.js';
import type { PluginProps } from './../../ricos-types/index.js';

import { dividerConverter } from '../divider-converter.js';
import { DividerViewer } from '../viewer/divider-viewer.js';

export const Divider: React.FC<PluginProps> = ({ node }) => {
  const ricosNode = React.useMemo(() => dividerConverter.fromPm.convert(node.toJSON()), [node]);

  return <DividerViewer node={ricosNode as DividerNode} />;
};
