import { Box, FormField, SegmentedToggle } from '@wix/design-system';
import type { IconComponent } from '@wix/wix-ui-icons-common/core';
import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import type { PluginContainerData_Alignment } from './../../../ricos-schema/next-schema/index.js';
import { Panel } from './../../../ui-components/panel/panel.js';

type AlignmentOption = {
  dataHook: string;
  icon: IconComponent;
  id: string;
  label: string;
};

export const DividerAlignmentPanel: React.FC<{
  closeModal: () => void;
  onSelect: (alignment: PluginContainerData_Alignment) => void;
  options: AlignmentOption[];
  selectedId: PluginContainerData_Alignment;
}> = ({ closeModal, onSelect, options, selectedId }) => {
  const { t } = useContext(RicosContext);

  return (
    <Panel closeButtonProps={{ onClick: closeModal }} height="fit-content">
      <Box direction="vertical" gap="SP3" padding="SP3">
        <FormField label={t('NodeAlignmentDropdown_Title')}>
          <SegmentedToggle
            ariaLabel={t('NodeAlignmentDropdown_Title')}
            fullWidth
            selected={selectedId}
            size="small"
            onClick={(_, alignment) => {
              onSelect(alignment as PluginContainerData_Alignment);
              closeModal();
            }}
          >
            {options.map(({ dataHook, icon: Icon, id, label }) => (
              <SegmentedToggle.Icon key={id} dataHook={dataHook} value={id} tooltipText={label}>
                <Icon />
              </SegmentedToggle.Icon>
            ))}
          </SegmentedToggle>
        </FormField>
      </Box>
    </Panel>
  );
};
