import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../../ricos-modals/modal-service-provider.js';
import { DividerData_Width } from './../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { IToolbarItem } from './../../../ricos-types/index.js';
import { DropdownButton } from './../../../_shared/dropdown-button.js';

import { alignmentMap } from './divider-buttons-data.js';

const getDefaultAlignment = (langDir: $TSFixMe) => {
  return langDir === 'rtl' ? 'RIGHT' : 'LEFT';
};

type Props = {
  toolbarItem: IToolbarItem;
  id: string;
  dataHook?: string;
};

export const DividerAlignmentButton: FC<Props> = ({ toolbarItem, dataHook, id }) => {
  const { t, languageDir } = useContext(RicosContext) || {};
  const isModalOpen = useModalState(getIsModalOpen(id));
  const node = toolbarItem.attributes.selectedNode;
  const [referenceElement, setReferenceElement] = useState<HTMLElement | null>(null);
  const getSelectedAlignment: () => string = () =>
    node?.attrs?.alignment || getDefaultAlignment(languageDir);
  const selectedAlignment = getSelectedAlignment();
  const SelectedAlignmentIcon = alignmentMap[selectedAlignment as keyof typeof alignmentMap];
  const isButtonDisabled = node?.attrs?.width === DividerData_Width.LARGE;

  return (
    <DropdownButton
      dataHook={dataHook}
      active={isModalOpen}
      onClick={() => {
        toolbarItem.commands?.click({ referenceElement });
      }}
      disabled={isButtonDisabled}
      ref={setReferenceElement}
      icon={SelectedAlignmentIcon}
      tooltip={t('TextAlignmentButton_Tooltip')}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
