import classNames from 'classnames';
import React from 'react';

import type { DividerData_LineStyle, DividerNode } from './../../ricos-schema/next-schema/index.js';

import { ROOT } from '../data-hooks.js';
import { getDividerRenderData } from '../get-divider-render-data.js';
import styles from '../statics/styles/divider-viewer-scss.js';

const DIVIDER_MIN_HEIGHT = 29;
const SAFARI_CARET_FIX_HEIGHT = 1;

export const DividerViewer: React.FC<{ node: DividerNode }> = ({ node }) => {
  const { lineStyle, width, alignment } = node.dividerData || {};
  const lineStyleAsLowerCase = lineStyle?.toLowerCase() as Lowercase<DividerData_LineStyle>;
  const renderData = getDividerRenderData(node.dividerData);
  const lineClassName = classNames(
    styles.divider,
    renderData.kind === 'legacy' ? styles['divider--legacy'] : styles['divider--lines'],
    styles[`divider--${lineStyleAsLowerCase}`],
    styles[`divider--${width?.toLowerCase()}`],
    styles[`divider--${alignment?.toLowerCase()}`]
  );
  return (
    <div
      className={styles['divider-container']}
      data-hook={`${ROOT} divider-${lineStyleAsLowerCase}`}
      role="separator"
      aria-orientation="horizontal"
      style={{
        height: Math.max(DIVIDER_MIN_HEIGHT, renderData.height + SAFARI_CARET_FIX_HEIGHT),
      }}
    >
      {
        //fixing Tiptap bug in Safari: when selecting node-view which is svg, there is a caret below, and you can't
        //focus on empty line below the node view
        //similar issue discussed here: https://discuss.prosemirror.net/t/ios-safari-does-not-hide-the-caret-on-non-visible-selections-e-g-nodeselection/3024
      }
      <div className={styles.svgFixerContainer}>
        {renderData.kind === 'legacy' ? (
          <svg className={lineClassName} height={renderData.height}>
            {renderData.lines.map((line, i) => (
              <line key={i} {...line} strokeLinecap={renderData.strokeLinecap} />
            ))}
          </svg>
        ) : (
          <div className={lineClassName} style={{ gap: renderData.lineGap }}>
            {renderData.lines.map(({ thickness, borderRadius, mask }, i) => (
              <div
                key={i}
                className={styles['divider-line']}
                style={{
                  height: thickness,
                  borderRadius,
                  backgroundColor: renderData.color,
                  ...(mask && {
                    // One trailing gap of overhang, clipped by the wrapper, cancels the last tile's
                    // gap so the last dash ends flush with the divider's edge. `space` (unlike
                    // `round`) never rescales the tiles, so that cancellation is exact and no dash
                    // is ever clipped.
                    width: `calc(100% + ${mask.overhang}px)`,
                    WebkitMaskImage: mask.image,
                    maskImage: mask.image,
                    WebkitMaskRepeat: 'space',
                    maskRepeat: 'space',
                  }),
                }}
              />
            ))}
          </div>
        )}
        <div className={styles.emptyChar}>&nbsp;</div>
      </div>
    </div>
  );
};
